79|function setActiveStore(index) {
80|  const options = [...$('store-results').querySelectorAll('.store-result')];
81|  if (!options.length) return;
82|  activeStoreIndex = (index + options.length) % options.length;
83|  options.forEach((option, optionIndex) => {
84|    const active = optionIndex === activeStoreIndex;
85|    option.classList.toggle('active', active);
86|    option.setAttribute('aria-selected', String(active));
87|  });
88|  const active = options[activeStoreIndex];
89|  $('store-search').setAttribute('aria-activedescendant', active.id);
90|  active.scrollIntoView({ block: 'nearest' });
