101|function renderStoreResults() {
102|  const results = $('store-results');
103|  const query = $('store-search').value.toLocaleLowerCase().trim();
104|  results.textContent = '';
105|  activeStoreIndex = -1;
106|  if (!query) {
107|    matchingStores = [];
108|    closeStoreResults();
109|    return;
110|  }
111|
112|  const terms = query.split(/\s+/).filter(Boolean);
113|  matchingStores = availableStores
114|    .filter((store) => terms.every((term) => storeText(store).includes(term)))
115|    .sort((left, right) => {
116|      const score = (store) => {
117|        const name = String(store.name || '').toLocaleLowerCase();
118|        const city = String(store.city || '').toLocaleLowerCase();
119|        const zip = String(store.zip || '').toLocaleLowerCase();
120|        if (zip === query) return 0;
121|        if (name.startsWith(query)) return 1;
122|        if (city.startsWith(query)) return 2;
123|        return 3;
124|      };
125|      return score(left) - score(right) || storeLabel(left).localeCompare(storeLabel(right));
126|    })
127|    .slice(0, 10);
128|
129|  if (!matchingStores.length) {
130|    const empty = document.createElement('p');
131|    empty.className = 'store-no-results';
132|    empty.textContent = 'No stores match that search.';
133|    results.append(empty);
134|  } else {
135|    matchingStores.forEach((store, index) => {
136|      const option = document.createElement('button');
137|      option.type = 'button';
138|      option.id = `store-result-${index}`;
139|      option.className = 'store-result';
140|      option.setAttribute('role', 'option');
141|      option.setAttribute('aria-selected', 'false');
142|      const name = document.createElement('strong');
143|      name.textContent = store.name;
144|      const detail = document.createElement('span');
145|      detail.textContent = [store.address, store.city, store.state, store.zip]
146|        .filter(Boolean).join(' · ');
147|      option.append(name, detail);
148|      option.addEventListener('click', () => chooseStore(store));
149|      results.append(option);
150|    });
151|  }
152|  results.hidden = false;
153|  $('store-search').setAttribute('aria-expanded', 'true');
