/* Boba Builder — one stylesheet, no build step. */

:root {
  --bg: #faf6f1;
  --bg-tint: #f2e9df;
  --card: #ffffff;
  --ink: #2c211b;
  --muted: #7b6a5e;
  --line: #e6dbcf;
  --brand: #7a4a28;
  --brand-soft: #f4e7db;
  --accent: #8a6ad4;
  --accent-soft: #efeaff;
  --ok: #2c7a58;
  --warn: #a06a12;
  --err: #b03b3b;
  --err-soft: #fceaea;
  --warn-soft: #fdf3e0;
  --ok-soft: #e8f5ee;
  --radius: 14px;
  --shadow: 0 1px 2px rgba(44, 33, 27, .06), 0 8px 24px rgba(44, 33, 27, .06);
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #17130f;
    --bg-tint: #211a15;
    --card: #201a15;
    --ink: #f2e9e0;
    --muted: #ac9a8c;
    --line: #3a2f26;
    --brand: #e6b58a;
    --brand-soft: #2e231a;
    --accent: #b3a0f0;
    --accent-soft: #272042;
    --ok: #7fd0a8;
    --warn: #e6b968;
    --err: #f09a9a;
    --err-soft: #3a2020;
    --warn-soft: #33280f;
    --ok-soft: #14291f;
    --shadow: 0 1px 2px rgba(0, 0, 0, .3), 0 8px 24px rgba(0, 0, 0, .25);
  }
}

* { box-sizing: border-box; }

body {
  margin: 0;
