report({name: loaded.name, drink: loaded.drink, size: loaded.size,
        sugar: loaded.sugar, toppings: loaded.toppings,
        quantity: loaded.quantity, notes: loaded.notes, item_id: loaded.item_id});
""")
        self.assertEqual(result, {
