{"content":"/* First-time organizer onboarding state. No accounts and no server: whether
   this browser has seen the intro is a localStorage flag, the same pattern as
   favorites and saved-order tokens. Storage that is missing, corrupt, or
   denied (private browsing) never breaks the page — the caller just shows the
   short version of the explainer. */
(function (root) {
  'use strict';

  const STORAGE_KEY = 'boba-builder:onboarding:v1';

  // One flag per confusing moment, so dismissing the entry intro does not
  // also silence the cart-handoff explainer and vice versa.
  const KINDS = ['entry', 'handoff'];

  function storageOrNull(storage) {
    if (storage) return storage;
    try {
      return root.localStorage || null;
    } catch (_error) {
      return null;
    }
  }

  function read(storage) {
    const store = storageOrNull(storage);
    if (!store) return {};
    try {
      const parsed = JSON.parse(store.getItem(STORAGE_KEY) || '{}');
      return parsed && typeof parsed === 'object' ? parsed : {};
    } catch (_error) {
      return {};
    }
  }

  function shouldShow(kind, storage) {
    if (KINDS.indexOf(kind) < 0) return false;
    return read(storage)['dismissed:' + kind] !== true;
  }

  function dismiss(kind, storage) {
    if (KINDS.indexOf(kind) < 0) return false;
    const store = storageOrNull(storage);
    if (!store) return false;
    const state = read(store);
    state['dismissed:' + kind] = true;
    try {
      store.setItem(STORAGE_KEY, JSON.stringify(state));
    } catch (_error) {
      return false;
    }
    return true;
  }

  function reset(storage) {
    const store = storageOrNull(storage);
    if (!store) return false;
    try {
      store.removeItem(STORAGE_KEY);
    } catch (_error) {
      return false;
    }
    return true;
  }

  root.BobaOnboarding = {
    STORAGE_KEY: STORAGE_KEY,
    KINDS: KINDS.slice(),
    shouldShow: shouldShow,
    dismiss: dismiss,
    reset: reset,
  };
}(typeof window !== 'undefined' ? window : this));
","path":"app/static/onboarding.js"}

{"find":"/* --- tabs ---------------------------------------------------------------- */","path":"app/static/app.js","replace":"/* --- first-time onboarding ------------------------------------------------- */

function onboarding() {
  try {
    return window.BobaOnboarding || null;
  } catch (error) {
    return null;
  }
}

function renderOnboarding() {
  const card = $('onboarding-card');
  const reopenRow = $('onboarding-reopen-row');
  if (!card || !reopenRow) return;
  // Without the module (or without storage) show the intro once per load and
  // offer no persistence: failing visible beats failing silent here.
  const firstTime = !onboarding() || onboarding().shouldShow('entry');
  card.hidden = !firstTime;
  reopenRow.hidden = firstTime;
}

function dismissOnboarding() {
  const guide = onboarding();
  if (guide) guide.dismiss('entry');
  renderOnboarding();
  const heading = $('start-h');
  if (heading && heading.focus) {
    // Keep keyboard users where the choice is, not stranded on a hidden card.
    try { heading.setAttribute('tabindex', '-1'); heading.focus(); } catch (error) { /* visual only */ }
  }
}

if ($('onboarding-dismiss')) $('onboarding-dismiss').addEventListener('click', dismissOnboarding);
if ($('onboarding-dismiss-top')) $('onboarding-dismiss-top').addEventListener('click', dismissOnboarding);
if ($('onboarding-reopen')) $('onboarding-reopen').addEventListener('click', () => {
  const guide = onboarding();
  if (guide) guide.reset();
  // Reset clears both moments; re-dismiss the handoff one so reopening the
  // entry intro does not re-nag about the cart step.
  if (guide) guide.dismiss('handoff');
  renderOnboarding();
});

renderOnboarding();

/* --- tabs ---------------------------------------------------------------- */"}

