{"find":"/* Cart-handoff explainer: the moment first-timers most often read as broken.
   Everyone sees the one-line version every time — it is the guard against
   "the tool built a cart and nothing happened". First-time organizers also
   get the expanded walkthrough until they dismiss it; the flag lives in
   localStorage next to the entry intro's, so returning organizers are never
   nagged. Works without BobaOnboarding (tests, blocked storage) by showing
   the short line with no dismiss button. */
function handoffExplainer() {
  const guide = (typeof window !== 'undefined' && window.BobaOnboarding) || null;
  let firstTime = true;
  try {
    firstTime = !guide || guide.shouldShow('handoff');
  } catch (_error) {
    firstTime = true;
  }
  const box = el('div', 'handoff-explainer');
  if (!firstTime) {
    box.append(el('p', 'muted handoff-short',
      'Building the cart opens an editable copy on the Kung Fu Tea site, where you review and pay.'));
    return box;
  }
  box.append(el('strong', null, 'What happens when you build the cart'));
  const steps = el('ol', 'handoff-steps');
  [
    'We build one Kung Fu Tea cart from the rows above, in this browser session.',
    'A link opens an editable copy of that cart on the Kung Fu Tea site.',
    'You review it there and pay there. Nothing is ordered or charged here.',
  ].forEach((text) => steps.append(el('li', null, text)));
  box.append(steps);
  if (guide) {
