/* --- first-time onboarding ------------------------------------------------ */

.text-button {
  background: none; border: none; padding: 0; font: inherit; cursor: pointer;
  color: var(--brand); text-decoration: underline; text-underline-offset: 2px;
}
.text-button:hover { color: var(--ink); }
.text-button:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

.onboarding-card { border-color: var(--accent); }
.onboarding-heading {
  display: flex; justify-content: space-between; align-items: start; gap: 1rem;
  margin-bottom: .6rem;
}
.onboarding-heading h2 { margin: 0; }
.onboarding-steps { margin: 0 0 .8rem; padding-left: 1.3rem; display: grid; gap: .35rem; }
.onboarding-chooser { margin-bottom: 1rem; }
.onboarding-chooser > p { margin: 0 0 .3rem; }
.onboarding-chooser ul { margin: 0; padding-left: 1.3rem; display: grid; gap: .25rem; }
.onboarding-chooser li { color: var(--muted); }
.onboarding-chooser li strong { color: var(--ink); }
.onboarding-card .actions { margin-top: 0; }
.onboarding-reopen { margin: 0 0 1rem; color: var(--muted); font-size: .9rem; }
.onboarding-reopen[hidden] { display: none; }

.handoff-explainer {
  margin: 0 0 1rem; padding: .8rem .9rem; border-radius: 10px;
  background: var(--accent-soft); font-size: .92rem;
}
.handoff-explainer > strong { display: block; margin-bottom: .35rem; }
.handoff-steps { margin: 0 0 .6rem; padding-left: 1.3rem; display: grid; gap: .25rem; }
.handoff-short { margin: 0; }","path":"app/static/app.css","replace":".converge-note strong { color: var(--ink); }"}

